```js
export function taxFor(cents, country) {
  const code = String(country).trim().toUpperCase();
  const entry = RATES[code];
  if (!entry) {
    throw new Error(`no VAT rate configured for country "${country}"`);
  }
  return Math.round(cents * entry.rate);
}
```

